// 붓 끝(13판: 기본 판 3장을 접선 방향 ±0.05D 로 미리 겹쳐 쓸어 둔 판 — 도장 간격 0.15D 로 찍어도 예전 0.05D 로 찍은 것과 같다. 11판: 알갱이는 r + 길이/2 <= 0.88R 안): 코덱스 10판 숫자 명세(가로로 길쭉한 알갱이 46 + 작은 알갱이 22, 확대 단계 판 153 · 612 개)로 코드가 그렸다. 만드는 법: 스크래치 grain/.
export const PENCIL_GRAIN_PNG = ''
export const PENCIL_TIPS = [
  '',
  '',
  '',
]
export const PENCIL_TIPS_K2 = [
  '',
  '',
  '',
]
// 붓 끝 그림 폭 대비 알갱이 묶음 실루엣 지름(11판: 알갱이를 반지름 0.88 안에만 둬 옆면 털이 없다 → 2·58·0.88/128)
export const PENCIL_TIP_DIAMETER = 0.7975

// 획 시작 · 끝 둥근 캡(2026-11-02 11판): 코덱스 8판 '거친 알갱이 원판'(128×128, 실루엣 지름 0.8795)을 첫 · 끝 도장 자리에 덧찍는다
export const PENCIL_CAP = ''
export const PENCIL_CAP_DIAMETER = 0.8795

// 12판 시험(PENCIL_BRUSH.sweep.on): 미리 쓸어 둔 가로 줄 묶음 붓 끝. 256×512 한 장에 128 높이 변형 4개를 위아래로 쌓았다(도장 번호 해시로 하나 고름).
// 알파는 거의 꽉 채우고(바깥 띠만 성김) 줄은 파랑(필압 깊이 채널)에 새겼다. 세로 실루엣 지름 d px, 길이 ell·지름. 확대 단계 판 없이 한 장을 쓴다. 만드는 법: 스크래치 grain/make_strip_tip2.py
export const PENCIL_SWEEP = { image: '', w: 256, h: 128, v: 4, d: 102, ell: 1.6 }

// 13판 시험(PENCIL_BRUSH.smallTip.on, 꺼짐): 얇은 선(굵기 <= smallTip.width) 전용 작은 붓 끝 — 알갱이 5개를 세로 줄마다 하나씩(48×48, 세로 실루엣 지름 40px). 줄마다 덮임이 보장돼 시드 운이 없다.
// 만드는 법: 스크래치 grain/make_small_tip.py (SEED=3 K=5 LEN=0.30,0.5 WID=0.16,0.22 AL=0.7,1.0)
export const PENCIL_SMALL = { image: '', size: 48, d: 40 }

// 22판 'copy' 엔진(PENCIL_BRUSH.engine === 'copy'): 시중 프로크리에이트 연필 브러시(_Kim Graphite 6B)의 엔진 구조(거친 덩어리 모양 도장 · 이진에 가까운 종이 고정 결 · 층 최대 불투명도)를 따르되,
// 그림은 우리가 원본의 통계(0 아닌 면적 · 평균 · 값 분포 · 한 덩어리 비율 / 평균 · 표준편차 · 양극 비율 · 자기상관)만 재현해 새로 만든 것이다(원본 그림은 앱에 없음).
// 모양: 256×256 흰색 + 알파(거친 덩어리). 결: 384×384 흰색 + 알파(밝을수록 칠함, 이진 69%), 알파 16단계, 이음새 없이 반복. 만드는 법: 스크래치 grain/make_copy_shape6.py · make_copy_grain.py
export const PENCIL_COPY = { shape: '', shapeSize: 256, grain: '', grainSize: 384 }

// 30판 흑연 퇴적 모델(PENCIL_BRUSH.deposit.on): 부드러운 둥근 돔 도장(128×128 흰색 + 알파, 알파 = 반지름 0.5R 까지 1, 그 밖은 (1 − u²)^1.5 (u = (r − 0.5R)/(0.5R)) — 경도 0.7(31판: 0.5 는 폭 절반 자리가 회색 · 구멍 — 참고 단면 가운데/중간 비 1.0~1.35) (30판 첫 돔 (1 − r²)^1.5 은 가장자리가 넓게 흐려 사용자 글씨가 안개처럼 번짐). 이 판을 Plus 로 쌓아 R 채널에 '묻은 흑연 양'을 만든다 —
// 가운데는 겹침이 많아 꽉 차고 옆 · 끝은 적게 묻어 종이 결에 걸러진다(참고 브러시의 진한 가운데 · 흐린 가장자리). 만드는 법: 위 식(numpy)
export const PENCIL_DOME = ''
export const PENCIL_DOME_DIAMETER = 0.9375

// 31판 섬유 돔(PENCIL_BRUSH.deposit.fiber 가 참이면 PENCIL_DOME 대신): 같은 돔에 가로(획 방향) 줄무늬(세로 σ 6px · 가로 σ 40px(판이 굵기 17px 로 줄면 세로 0.8px) 가우시안 잡음, 세기 0.45)를 곱했다.
// 도장을 접선 방향으로 돌려 찍으므로 줄무늬가 획을 따라 이어져 참고 연필의 획 방향 긁힘(길쭉함 3.5~6)을 낸다. 돔만 쓰면 방향 없는 점박이(조사 담당 30판: 길쭉 1.38 · 스펀지 판정)
export const PENCIL_DOME_FIBER = ''

// 32판 결 두 벌(획 모양부터 다시, 2026-11-03). 만드는 법: 띠 통과 잡음(저주파 제거 — 어느 구간이든 평균이 안정해 획이 끊기거나 얼룩지지 않는다)을 순위로 0~1 균등화.
// 종이 이빨: 256×256 등방, σ .55 + .35·σ 1.1, 고역 통과 3 · 4px(34판: σ .45 는 1px 모래, σ .8 은 번짐). 가닥: 512×128(가로 = 획 방향, 세로 = 법선), 법선 σ .8 · 획 방향 σ 5.5 + .7·(σ 1.8 · 14), 가닥이 2px 흐름 — 참고 연필 실측(획 방향 상관 8~10px, 법선 1.6px)에 맞춘 값
export const PENCIL_TOOTH_PNG = ''
